selector_to_html = {"a[href=\"#one-device-standard-pytorch-apis\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">One device, standard PyTorch APIs<a class=\"headerlink\" href=\"#one-device-standard-pytorch-apis\" title=\"Link to this heading\">#</a></h2><p>Every supported accelerator is programmed through the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device. Model code, optimizers, and third-party libraries keep using standard PyTorch APIs; moving between accelerators does not require changing tensor device strings, kernel launches, or the model.</p><p>The device module is installed at import time with <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.utils.rename_privateuse1_backend(\"flagos\")</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._register_device_module()</span></code>, so <code class=\"docutils literal notranslate\"><span class=\"pre\">device=\"flagos\"</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.flagos.*</span></code> methods, tensor methods, and storage work the same way as a first-class PyTorch device.</p>", "a[href=\"#execution-paths\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Execution paths<a class=\"headerlink\" href=\"#execution-paths\" title=\"Link to this heading\">#</a></h2><p>PyTorch-Plugin-FL implements four operator execution strategies, and a platform may combine several of them. These are implementation strategies, not user-selectable product tiers.</p>", "a[href=\"../architecture/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler Integration<a class=\"headerlink\" href=\"#profiler-integration\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler</span></code> supports the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device through a device tracer compiled into the wheel. A trace from <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler.profile(activities=[CPU,</span> <span class=\"pre\">PrivateUse1])</span></code> is structurally equivalent to the trace of the same workload on <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code>:</p>", "a[href=\"#hardware-support\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware support<a class=\"headerlink\" href=\"#hardware-support\" title=\"Link to this heading\">#</a></h2><p>Per-capability detail \u2014 including <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code>, distributed and profiler status per platform \u2014 is in the <a class=\"reference internal\" href=\"../reference/compatibility.html\"><span class=\"doc\">compatibility matrix</span></a>.</p>", "a[href=\"#training-stack\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Training stack<a class=\"headerlink\" href=\"#training-stack\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../architecture/torch-compile.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">torch.compile Integration<a class=\"headerlink\" href=\"#torch-compile-integration\" title=\"Link to this heading\">#</a></h1><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device supports <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code> for automatic kernel fusion and reduced dispatch overhead. The graph stays on the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device: there is no device round trip and no copy at the graph boundary.</p>", "a[href=\"#features\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Features<a class=\"headerlink\" href=\"#features\" title=\"Link to this heading\">#</a></h1><h2>One device, standard PyTorch APIs<a class=\"headerlink\" href=\"#one-device-standard-pytorch-apis\" title=\"Link to this heading\">#</a></h2><p>Every supported accelerator is programmed through the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device. Model code, optimizers, and third-party libraries keep using standard PyTorch APIs; moving between accelerators does not require changing tensor device strings, kernel launches, or the model.</p><p>The device module is installed at import time with <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.utils.rename_privateuse1_backend(\"flagos\")</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._register_device_module()</span></code>, so <code class=\"docutils literal notranslate\"><span class=\"pre\">device=\"flagos\"</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.flagos.*</span></code> methods, tensor methods, and storage work the same way as a first-class PyTorch device.</p>", "a[href=\"#observability\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Observability<a class=\"headerlink\" href=\"#observability\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#framework-and-ecosystem-compatibility\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Framework and ecosystem compatibility<a class=\"headerlink\" href=\"#framework-and-ecosystem-compatibility\" title=\"Link to this heading\">#</a></h2><p>Import-time shims adapt other projects\u2019 assumptions about the device, all of them optional and measurable through their own switch:</p>", "a[href=\"#low-precision-and-quantization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Low-precision and quantization<a class=\"headerlink\" href=\"#low-precision-and-quantization\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl.quantization</span></code> provides low-precision conversion helpers and modules:</p>", "a[href=\"../reference/compatibility.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Compatibility and Platform Support<a class=\"headerlink\" href=\"#compatibility-and-platform-support\" title=\"Link to this heading\">#</a></h1><h2>Status definitions<a class=\"headerlink\" href=\"#status-definitions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#per-operator-backend-routing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Per-operator backend routing<a class=\"headerlink\" href=\"#per-operator-backend-routing\" title=\"Link to this heading\">#</a></h2><p>Each built wheel ships one routing table, <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/configs/backends_&lt;platform&gt;.conf</span></code>, holding <code class=\"docutils literal notranslate\"><span class=\"pre\">op</span> <span class=\"pre\">=</span> <span class=\"pre\">backend</span></code> entries for the platform it was built for. Routing is decided per operator \u2014 not per device or per model \u2014 and can mix backends inside one model:</p>", "a[href=\"../architecture/distributed.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Distributed Collectives<a class=\"headerlink\" href=\"#distributed-collectives\" title=\"Link to this heading\">#</a></h1><p>PyTorch-Plugin-FL provides distributed support for the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device through <code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessGroupFlagOS</span></code>, a native <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.ProcessGroup</span></code> subclass. It is registered at import, so <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.init_process_group(\"flagos\")</span></code> works with no <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.*</span></code> monkeypatching.</p>", "a[href=\"#device-runtime-and-management-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Device runtime and management API<a class=\"headerlink\" href=\"#device-runtime-and-management-api\" title=\"Link to this heading\">#</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.flagos</span></code> module exposes a complete device interface:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
